-- 2026-09-28 채용공고 직군(job_field)·직무(job_role)를 enum 이름으로 바꾼다
--
-- 운영은 ddl-auto=none이므로 두 API를 배포하기 전에 적용한다. 컬럼 형식은 그대로(varchar(100))이고 값만 바꾼다.
-- 이 SQL이 없으면 새 서버가 원문 문자열을 enum으로 읽지 못해 채용공고 조회가 500이 된다.
-- 이미 enum 이름인 행은 건드리지 않으므로 배포 직전·직후에 다시 실행해도 된다.
--
-- 기존 값은 다음처럼 옮긴다. 맞는 값이 없으면 null로 둔다.
-- - 크롤러·기업회원: 직군·직무 라벨(예: `IT·개발`, `서버·백엔드`)과 같으면 그 enum으로 옮긴다.
-- - 고용24 수집분: 직무에 고용24 직종 이름(예: `응용 소프트웨어 개발자`)이 들어 있어 Work24JobRoles 표의 세분류 이름으로 옮긴다.
-- - 직군은 직무가 있으면 직무가 속한 직군으로 맞추고, 직무가 없으면 직군 라벨로 옮긴다.

-- 1. 현재 상태를 확인한다.
select job_field, job_role, count(*) from jobs group by job_field, job_role order by count(*) desc;

-- 2. 직무를 옮긴다. 이미 enum 이름인 행은 제외한다.
update jobs
set job_role = case
        when job_role = '서버·백엔드' then 'IT_BACKEND'
        when job_role = '프론트엔드' then 'IT_FRONTEND'
