        when job_field in ('IT_DEVELOPMENT', 'AI_DATA', 'GAME', 'DESIGN', 'PLANNING_STRATEGY', 'MARKETING_ADVERTISING', 'MERCHANDISING', 'SALES', 'TRADE_LOGISTICS', 'TRANSPORT_DELIVERY', 'LEGAL', 'HR_GENERAL_AFFAIRS', 'ACCOUNTING_TAX_FINANCE', 'SECURITIES_ASSET_MANAGEMENT', 'BANKING_CARD_INSURANCE', 'ENGINEERING_RND', 'CONSTRUCTION_ARCHITECTURE', 'PRODUCTION_SKILLED_TRADES', 'MEDICAL_HEALTH', 'PUBLIC_WELFARE', 'EDUCATION', 'MEDIA_ENTERTAINMENT', 'CUSTOMER_SERVICE_TM', 'SERVICE', 'FOOD_BEVERAGE') then job_field
    end
where job_field is not null or job_role is not null;

-- 4. 결과를 확인한다. 직무나 직군이 null로 바뀐 행은 원문을 분류하지 못한 공고다.
select job_field, job_role, count(*) from jobs group by job_field, job_role order by count(*) desc;
